-- Imported by scripts/import-questions.ts from C:\Users\Cambo\Downloads\population31approved-questions.json.

insert into public.questions (
  id, category, measure, subtype, prompt, answer, min, max, scale, unit,
  reference_year, source_title, source_url, explanation, is_daily
) values
  ('pop-india-2026', 'population', 'population', 'country', 'India overtook China to become the world''s most populous country despite a fertility rate that has already fallen below replacement — what is the UN-based country-total estimate for India in 2026?', 1476625576, 300000000, 3000000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'India''s fertility rate is now around 1.93, under the 2.1 needed to hold steady. It keeps growing only because its median age is 29 — decades of past births still working through the system.', false),
  ('pop-pakistan-2026', 'population', 'population', 'country', 'Pakistan has the highest fertility rate of any large Asian country and loses over a million people a year to emigration — what is the country-total estimate for Pakistan in 2026?', 259299791, 60000000, 600000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'At 3.44 children per woman and a median age under 21, Pakistan adds around four million people annually even after net emigration of over a million.', false),
  ('pop-bangladesh-2026', 'population', 'population', 'country', 'Bangladesh crams over 1,300 people into every square kilometre, by far the densest of any large country — what is the country-total estimate for Bangladesh in 2026?', 177818044, 40000000, 400000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Bangladesh fits more people than Russia into an area smaller than England and Scotland combined, and only 43% of them live in cities.', false),
  ('pop-japan-2026', 'population', 'population', 'country', 'Japan has a median age of 50 and is shrinking by roughly two thousand people every day — what is the country-total estimate for Japan in 2026?', 122427731, 60000000, 260000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Japan is losing around 675,000 people a year even while gaining 128,000 through migration — deaths outnumber births by a margin no realistic immigration policy could close.', false),
  ('pop-egypt-2026', 'population', 'population', 'country', 'Almost everyone in Egypt lives on the thin green ribbon of the Nile, and only 41% of them live in cities — what is the country-total estimate for Egypt in 2026?', 120101175, 30000000, 220000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Egypt''s nominal density looks modest at 121 per square kilometre, but that averages across the Sahara — the habitable strip along the river is among the most crowded land on Earth.', false),
  ('pop-dr-congo-2026', 'population', 'population', 'country', 'DR Congo has a median age of under 16 and the highest fertility rate of any country this size, growing over 3% a year — what is the country-total estimate for DR Congo in 2026?', 116452162, 25000000, 260000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'At 5.8 children per woman, DR Congo is adding 3.6 million people a year — roughly a Croatia every year — and is projected to become one of the world''s largest countries this century.', false),
  ('pop-vietnam-2026', 'population', 'population', 'country', 'Vietnam is still under half urban despite decades of rapid industrialisation — what is the country-total estimate for Vietnam in 2026?', 102177431, 40000000, 130000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Vietnam crossed 100 million recently, but its fertility rate of 1.86 is already below replacement and growth has slowed to 0.57% a year.', false),
  ('pop-germany-2026', 'population', 'population', 'country', 'Germany is shrinking by around 430,000 people a year even after gaining 158,000 through migration — what is the country-total estimate for Germany in 2026?', 83644258, 45000000, 110000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Germany''s median age of 45.7 means deaths now outpace births by a wide margin. It remains the EU''s largest country by a considerable distance despite the decline.', false),
  ('pop-tanzania-2026', 'population', 'population', 'country', 'Tanzania is growing at nearly 3% a year with a median age under 18, and has roughly doubled in size since 2000 — what is the country-total estimate for Tanzania in 2026?', 72563780, 15000000, 160000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'At 4.41 children per woman and only 41% urban, Tanzania adds around two million people a year — more than Thailand, Italy and Japan lose between them.', false),
  ('pop-colombia-2026', 'population', 'population', 'country', 'Colombia is one of the few countries in the Americas gaining more people through immigration than it loses, largely from the Venezuelan exodus — what is the country-total estimate for Colombia in 2026?', 53936226, 15000000, 120000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Colombia is over 80% urban with fertility down to 1.6, so its 0.96% growth leans heavily on net migration of about 116,000 a year.', false),
  ('pop-canada-2026', 'population', 'population', 'country', 'Canada is the second-largest country on Earth by land area but averages only four people per square kilometre — what is the country-total estimate for Canada in 2026?', 40467728, 12000000, 90000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'With fertility at 1.33, essentially all of Canada''s growth comes from net migration of around 291,000 a year — one of the highest per-capita intakes in the world.', false),
  ('pop-poland-2026', 'population', 'population', 'country', 'Poland is shrinking faster than almost any large European country, losing nearly 300,000 people a year — what is the country-total estimate for Poland in 2026?', 37843188, 15000000, 90000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Poland combines a fertility rate of 1.31 with net emigration, giving a decline of 0.78% a year — steeper than Japan''s. Only 60% of the country lives in cities.', false),
  ('pop-chile-2026', 'population', 'population', 'country', 'Chile''s fertility rate has collapsed to 1.12, among the lowest outside East Asia, and it is 85% urban — what is the country-total estimate for Chile in 2026?', 19945850, 5000000, 45000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Chile stretches 4,300 km down the continent but averages 27 people per square kilometre, with almost everyone concentrated in the central valley around Santiago.', false),
  ('pop-singapore-2026', 'population', 'population', 'country', 'Singapore packs over 8,400 people into every square kilometre of its 700 km² territory, one of the densest sovereign states on Earth — what is the country-total estimate for Singapore in 2026?', 5905748, 2000000, 9000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'Singapore''s fertility rate of 0.97 is among the world''s lowest, so its continued growth of 0.6% a year comes entirely from immigration.', false),
  ('pop-new-zealand-2026', 'population', 'population', 'country', 'New Zealand covers more land than the United Kingdom but holds a fraction of the people, at around 20 per square kilometre — what is the country-total estimate for New Zealand in 2026?', 5287479, 1500000, 12000000, 'linear', 'people', '2026', 'Worldometer — Countries in the world by population (2026), from UN World Population Prospects 2024 revision', 'https://www.worldometers.info/world-population/population-by-country/', 'New Zealand crossed five million only recently, and with fertility at 1.64 its 0.68% growth depends on net migration of around 16,000 a year.', false),
  ('agg-jakarta-2025', 'population', 'population', 'city', 'Jakarta overtook Tokyo to become the largest urban area on Earth, and Indonesia is moving its capital elsewhere partly because the city is sinking — how many people did the UN count in the Jakarta urban area in 2025?', 41913860, 8000000, 70000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Jakarta sprawls across 4,883 km² at over 8,500 people per square kilometre and is projected to reach nearly 52 million by 2050, despite parts of North Jakarta subsiding several centimetres a year.', false),
  ('agg-delhi-2025', 'population', 'population', 'city', 'The Delhi urban area packs over 14,000 people into every square kilometre, more than double Tokyo''s density — how many people did the UN count there in 2025?', 30222405, 12000000, 45000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Delhi fits its population into 2,101 km², less than half Tokyo''s footprint. The UN projects it will approach 34 million by 2050.', false),
  ('agg-shanghai-2025', 'population', 'population', 'city', 'Shanghai is the largest urban area in China and one of the few still growing above 1% a year — how many people were in the Shanghai urban area in 2025?', 29558908, 6000000, 60000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Shanghai is growing at 1.31% even as China''s national population falls — internal migration is concentrating people into a handful of coastal cities.', false),
  ('agg-cairo-2025', 'population', 'population', 'city', 'Cairo is the densest of the world''s ten largest urban areas, at over 15,000 people per square kilometre — how many were in the Cairo urban area in 2025?', 25566102, 8000000, 35000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Cairo squeezes its population into just 1,645 km², hemmed in by desert on both sides. Egypt has been building an entirely new administrative capital 45 km east partly to relieve it.', false),
  ('agg-manila-2025', 'population', 'population', 'city', 'Manila''s urban area is one of the largest in the world but sits on just 2,438 square kilometres across a typhoon-exposed bay — how many people were there in 2025?', 24735305, 6000000, 60000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Metro Manila is a patchwork of 16 separate cities plus a municipality under one authority, at over 10,000 people per square kilometre.', false),
  ('agg-seoul-2025', 'population', 'population', 'city', 'Roughly 44% of all South Koreans live in the Seoul urban area, which is now barely growing at all — how many people did the UN count there in 2025?', 22490482, 5000000, 45000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Seoul grew 0.23% in the year to 2025 and is projected to shrink to 21.2 million by 2050, dragged down by the world''s lowest fertility rate.', false),
  ('agg-karachi-2025', 'population', 'population', 'city', 'Karachi is the most crowded major urban area on Earth, with nearly 25,000 people per square kilometre crammed into 870 km² — how many lived there in 2025?', 21422590, 4000000, 50000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Karachi''s footprint is roughly a third of Delhi''s but holds two-thirds as many people. Growing at nearly 2% a year, it''s projected to pass 32 million by 2050.', false),
  ('agg-sao-paulo-2025', 'population', 'population', 'city', 'São Paulo is the largest urban area in the Southern Hemisphere and the UN expects it to be smaller in 2050 than it is today — how many people were there in 2025?', 18949790, 4000000, 40000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Growth has slowed to 0.16% a year and Brazil''s fertility rate is now 1.59, so the UN projects São Paulo will peak and then edge down to around 18.2 million by 2050.', false),
  ('agg-bangkok-2025', 'population', 'population', 'city', 'Bangkok dominates Thailand so completely that it has no real rival city, and its urban area sprawls over 2,661 square kilometres — how many people were in it in 2025?', 18180280, 3000000, 45000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Bangkok is still growing at 1% a year even though Thailand''s national population is falling — one of the starkest urban-rural divergences anywhere.', false),
  ('agg-mexico-city-2025', 'population', 'population', 'city', 'Mexico City''s urban area sits at 2,200 metres in a drained lake basin and has essentially stopped growing, at 0.14% a year — how many people were there in 2025?', 17734212, 6000000, 24000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'The UN projects Mexico City will be almost exactly the same size in 2050 as today — a rare case of a megacity flatlining rather than growing or shrinking.', false),
  ('agg-istanbul-2025', 'population', 'population', 'city', 'Istanbul is the largest urban area in Europe and the only megacity spanning two continents, on just 1,268 square kilometres — how many people were there in 2025?', 15014763, 3000000, 35000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'At nearly 12,000 people per square kilometre, Istanbul is roughly twice as dense as London and sits directly on the North Anatolian Fault.', false),
  ('agg-buenos-aires-2025', 'population', 'population', 'city', 'Around a third of all Argentines live in the Buenos Aires urban area, which has barely changed size in years — how many people were there in 2025?', 14017736, 3000000, 40000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Growing at just 0.11% a year, Buenos Aires is projected to add barely 200,000 people over the next 25 years. Argentina is 96.5% urban, among the highest anywhere.', false),
  ('agg-new-york-2025', 'population', 'population', 'city', 'New York is the only urban area in the top 25 that is both shrinking and unusually spread out, at barely 5,000 people per square kilometre — how many were there in 2025?', 13920148, 4000000, 32000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'New York''s urban area covers 2,691 km², more than Delhi''s, for less than half the people. It contracted 0.18% in the year to 2025.', false),
  ('agg-lagos-2025', 'population', 'population', 'city', 'Lagos is Africa''s largest urban area and is projected to add over three million people by 2050 — how many were there in 2025?', 12791699, 2000000, 35000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Lagos is often quoted at 20 million or more; the UN''s urban-area definition puts it lower. Either way it''s growing at 1.23% a year on 1,231 km² of lagoon and reclaimed land.', false),
  ('agg-luanda-2025', 'population', 'population', 'city', 'Luanda is the fastest-growing large urban area on Earth at nearly 3% a year, and the UN expects it to almost double by 2050 — how many people were there in 2025?', 11370127, 3000000, 16000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'Luanda is projected to reach over 20 million by 2050, which would make it larger than São Paulo is today. Angola''s fertility rate of 4.89 is doing most of the work.', false),
  ('agg-paris-2025', 'population', 'population', 'city', 'The Paris urban area has essentially stopped growing, at 0.08% a year, and the UN projects it will be marginally smaller in 2050 — how many people were there in 2025?', 9381921, 2000000, 28000000, 'linear', 'people', '2025', 'Worldometer — Largest Cities in the World (2025), from UN World Urbanization Prospects 2025 Revision', 'https://www.worldometers.info/population/largest-cities-in-the-world/', 'The gap between the Paris urban area and the City of Paris is one of the widest in the world — the administrative commune holds barely a fifth of the people counted here.', false)
on conflict (id) do nothing;
